#!/usr/bin/env python3
"""Build an offline HTML guide from reviewed, local JSON and configuration files."""
from pathlib import Path
from html import escape as e
import json,re
R=Path(__file__).resolve().parents[1]; G=R/'guide'
def code(s):return '<code>'+e(s)+'</code>'
def keys(s):return '<kbd>'+e(s)+'</kbd>'
def table(headers,rows):return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+e(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+v+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def section(id,num,title,body):return f'<section id="{id}"><div class="section-label">{num}</div><h2>{title}</h2>{body}</section>'
ray=json.loads((G/'raycast-shortcuts.json').read_text());tools=json.loads((G/'tool-inventory.json').read_text())
nav=[('raycast','Raycast & global keys'),('workflow','Everyday workflows'),('vscode','VS Code'),('shell','Terminal & Git'),('vim','Neovim & tmux'),('directory','Installed tools'),('manage','Manage this setup')]
parts=['''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nir's Mac — Tools & shortcuts</title><meta name="description" content="A local field guide to Nir's Mac: verified Raycast hotkeys, VS Code, shell commands and optional Neovim."><link rel="stylesheet" href="style.css"><link rel="icon" type="image/svg+xml" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Crect width='40' height='40' rx='8' fill='%23102a43'/%3E%3Ctext x='7' y='29' font-size='26' font-family='monospace' fill='%23ff946c'%3E%3E_%3C/text%3E%3C/svg%3E"></head><body id="top"><aside class="sidebar"><div class="brand">nir<span>.</span> / mac</div><div class="eyebrow">Personal field guide</div><nav aria-label="Guide sections">'''+''.join(f'<a href="#{id}">{title}</a>' for id,title in nav)+'''</nav><footer>Verified 26 September 2026<br>Stored with your dotfiles.<br>Find anything with ⌘ F.</footer></aside><main><header><div class="eyebrow">Your computer · Your conventions</div><h1>Tools & shortcuts.</h1><p class="intro">Open the right app, move a window, jump back to an edit. A reference for the way your Mac is configured.</p><div class="strip"><div><strong>21</strong><span>Raycast command hotkeys</span></div><div><strong>⌥ Space</strong><span>Open Raycast</span></div><div><strong>Right ⌥</strong><span>Your Hyper key</span></div></div></header>''']
body='<p>Raycast itself provides your Hyper key (Settings → Keyboard, Include Shift enabled). Hold <strong>Right Option</strong> to send Hyper: Control + Option + Shift + Command. Left Option keeps its normal behavior. These assignments were read from the current Raycast settings, including the enabled state.</p><div class="note"><strong>Read the symbols</strong><br>⌘ Command · ⌥ Option · ⌃ Control · ⇧ Shift · ⇥ Tab · ↵ Return. '+keys('⌃ ⌃')+' means a double press of Control.</div>'
for category in ['Launcher','Applications','Extensions','Window Management']:
 rows=[(e(x['command']),keys(x['keys']),code(x['alias']) if x['alias'] else '—') for x in ray['shortcuts'] if x['category']==category]
 body+='<h3>'+category+'</h3>'+table(['Action','Global shortcut','Raycast alias'],rows)
body+='<p class="muted">“ChatGPT” and “ChatGPT Classic” are the labels Raycast currently shows. The alias '+code('codex')+' belongs to ChatGPT in that list. Hyper + O opens the Ollama AI extension’s Improve Writing command. OCR and clipboard commands are global, so they can override a focused app’s Control shortcuts.</p>'
body+='<h3>Keyboard navigation outside Raycast</h3>'+table(['Tool','Shortcut','Use'],[(e('Homerow'),keys('Hyper H'),'Control app buttons and links from the keyboard: show hints, then type a hint to click.'),(e('Homerow'),keys('Hyper J'),'Start keyboard scrolling. Arrow-key scrolling is enabled.'),(e('AltTab'),keys('⌘ Tab')+' / '+keys('⌘ `'),'Window switching, as documented in your older setup notes. These AltTab bindings have not been re-verified live.')])
body+='<p><a href="raycast-shortcuts.json">Reviewed hotkey data</a> · <code>preferences/homerow.json</code> records the current Homerow mappings. These are your daily controls across supported apps: Hyper H for clicking and Hyper J for scrolling. Hyper is Right Option, provided by Raycast. The installed Homerow uses com.superultra.Homerow; an older preference file has the H/J keys reversed.</p>'
body+='<h3>Native macOS screen zoom</h3><p>Hold '+keys('Right Ctrl')+' and scroll the mouse wheel to zoom in or out. This is configured in <strong>System Settings → Accessibility → Zoom</strong>: enable “Use scroll gesture with modifier keys to zoom”, choose <strong>Control</strong>, and use <strong>Full Screen</strong> zoom. macOS selects Control without distinguishing left from right; Right Ctrl is your preferred key.</p><p>The scroll-to-zoom toggle and Control modifier values were read from this Mac on 30 September 2026 and are saved in <code>preferences/macos.json</code>. <code>./setup install</code> (unless <code>--skip-preferences</code>) or <code>./setup defaults</code> applies them with per-key backups. For the installed macos-defaults tool, preview with <code>macos-defaults --dry-run apply macos-defaults/zoom.yaml</code> and apply with <code>macos-defaults apply macos-defaults/zoom.yaml</code>; that direct tool command does not create the setup backup. Log out and back in if needed, then verify Right Ctrl + wheel and Full Screen style. <a href="https://support.apple.com/guide/mac-help/change-zoom-settings-for-accessibility-mh40579/mac">Apple’s Zoom settings reference</a>.</p>'
body+='<h3>Your local Raycast extensions</h3><p>These 75 extension packages are present on this Mac. Open Raycast and search a command title to use it; individual commands may be disabled or require an account. This list is read from extension manifests and does not include their private preferences.</p>'
for extension in json.loads((G/'raycast-extensions.json').read_text()):
    body+='<details><summary>'+e(extension['name'])+'</summary><div class="detail-body"><p>'+e(extension['description'])+'</p>'+table(['Search command','Purpose'],[(e(x['name']),e(x['description'])) for x in extension['commands']])+'</div></details>'
parts.append(section('raycast','01 / LAUNCH & MOVE','Raycast & global keys',body))
body='''<p>Start with a task, then reach for the tool you already configured.</p><div class="grid">
<article class="panel"><h3>Start coding</h3><p>Press <kbd>Hyper I</kbd> for VS Code. Use <kbd>⌘ E</kbd> to find a file, <kbd>⌘ ↑</kbd> / <kbd>⌘ ↓</kbd> to jump between code blocks, and <kbd>⇧ ⌘ Backspace</kbd> to return to the last edit.</p><p>In a terminal: <code>pp</code> → <code>j project-name</code> → <code>code .</code> → <code>prd</code>. Use <code>rs</code> when you need to choose a package script.</p></article>
<article class="panel"><h3>Put two things side by side</h3><p>Focus one window and press <kbd>⌃ ⌥ ←</kbd>. Focus the other and press <kbd>⌃ ⌥ →</kbd>. Move a window between displays with <kbd>⌃ ⌥ ⌘ ←</kbd> / <kbd>⌃ ⌥ ⌘ →</kbd>.</p><p><kbd>⌃ ⌥ Return</kbd> maximizes the current window. These are Raycast commands.</p></article>
<article class="panel"><h3>Work with text</h3><p><kbd>⌃ V</kbd> opens clipboard history. <kbd>⌃ O</kbd> recognizes text from the screen. <kbd>⌃ ⌃</kbd> looks up a word. <kbd>Hyper O</kbd> runs Improve Writing through the Ollama AI extension.</p><p>Your separate “Fix Spelling and Grammar” script reads the clipboard, calls local Ollama on port 11434 with model <code>phi3</code>, and copies the result back. It has no verified global hotkey.</p></article>
<article class="panel"><h3>Browse and capture</h3><p><kbd>Hyper B</kbd> opens Chrome; <kbd>Hyper N</kbd> opens Obsidian. Your saved Vimium convention is <kbd>f</kbd> to click a link and <kbd>⇧ F</kbd> to open it in a new tab. This comes from your setup notes, not a live browser export.</p><p>For a selected area, <kbd>⌃ ⌘ ⇧ 4</kbd> copies to the clipboard; <kbd>⌘ ⇧ 4</kbd> saves a file in <code>/tmp</code>. These are your native macOS shortcuts. Use Zappy for images, GIFs and quick videos; use QuickTime Player for better-quality video.</p></article>
</div><h3>Useful Raycast search commands</h3><p>Open Raycast with <kbd>⌥ Space</kbd>, type the command, then press Return.</p>'''
body+=table(['Search for','What to do'],[(code('projects'),'List Git repositories with your Git Repos extension.'),(code('quit'),'Quit Non-Focused from Single Focus. Save work first.'),(code('kill port'),'Find a listening port with Port Manager.'),(code('close app'),'Find a process with Kill Process; terminating it can lose unsaved work.'),(e('To Hebrew / To Latin'),'Convert keyboard-layout text with Aleph Tools.'),(e('Search Files / Search Snippets / Create Snippet'),'Find a file, insert reusable text, or save a new snippet.'),(e('Open dotfiles'),'Your script opens this repository in VS Code after its script directory is registered.'),(e('Open blog / Open eslint config / Work mode'),'Preserved personal script commands; project paths still follow your own repository locations.')])
body+='<p class="muted">Aliases above were visible in your Raycast launcher. Extension accounts, models and permissions stay in Raycast. For a new Mac, use Raycast Cloud Sync or a fresh export; the saved 2025 export is historical.</p>'
capture=json.loads((R/'preferences/capture-workflow.json').read_text())
dictation=json.loads((R/'preferences/dictation.json').read_text())
body+='<h3>Dictate text</h3>'+table(['Setting','Your workflow'],[(e('Default app'),e(dictation['app'])+' — built into macOS.'),(e('Start / stop'),keys('Right ⌘ twice')+' — '+e(dictation['shortcut'])+'.'),(e('Languages'),e(' and '.join(dictation['languages']))),(e('Microphone source'),e(dictation['microphone']))])
body+='<p>Click a text field, press Right Command twice, and speak. Type corrections while dictating; press the shortcut again or Escape to finish. Switch languages using the indicator beside the cursor. Handy and other installed dictation apps are optional alternatives.</p>'
body+='<p class="muted">Verified '+e(dictation['verified'])+' in System Settings → Keyboard → Dictation. The default install and <code>./setup defaults</code> restore enablement, languages and this shortcut while preserving other system shortcuts. You can also run <code>macos-defaults apply macos-defaults/dictation.yaml</code> (preview with <code>--dry-run</code>). On a new Mac, verify Automatic microphone selection and let macOS download speech assets. <a href="../manual-install/dictation.md">Dictation settings and restore</a> · <a href="https://support.apple.com/guide/mac-help/dictate-messages-and-documents-mh40584/mac">Apple Dictation guide</a>.</p>'
quick_app=capture['quick_gif_video']['app']
body+='<h3>Capture and record</h3>'+table(['Task','Tool or shortcut'],[(e('Selected area → clipboard'),keys('⌃ ⌘ ⇧ 4')+' — select an area, then paste where needed.'),(e('Selected area → file'),keys('⌘ ⇧ 4')+' — select an area; the current save destination is '+code(capture['save_location'])+'.'),(e('Image capture / markup'),e(capture['images'])),(e('Quick GIF or short casual recording'),e(quick_app)),(e('Better-quality video'),e(capture['better_video'])+' — your preferred recording tool.')])
body+='<p class="muted">Save location verified from this Mac; tool preferences supplied by you. Zappy is confirmed for images, GIFs and quick videos. <a href="https://support.apple.com/en-us/102646">Apple screenshot shortcuts</a>.</p>'
body+='<p>Shottr is also installed and was running when checked, but it is not part of your confirmed capture workflow. Consider removing it unless you use its scrolling captures, pixel measurements or image-cleanup tools. <a href="https://shottr.cc/">Shottr features</a>.</p>'
parts.append(section('workflow','02 / COMMON TASKS','Everyday workflows',body))
body='''<p>VS Code remains your default editor. Your Default, Home, Work and Cursor Default configurations are preserved. “Cursor Default” is a VS Code profile name, not a switch to the Cursor app.</p><p>The main coding profile uses JetBrains Mono at 16px, Webstorm Darcula, wrapped lines, and language-specific formatters. It limits each editor group to five tabs and keeps preview tabs disabled.</p>'''
labels={'git.revertSelectedRanges':'Discard selected changed lines','gotoLastEdit.goBack':'Go back to the last edit','gotoLastEdit.goForward':'Go forward through edits','editsHistory.moveCursorToNextEdit':'Next edit (Edits History extension)','workbench.action.quickOpen':'Find and open a file','block-travel.jumpUp':'Jump to previous code block','block-travel.jumpDown':'Jump to next code block','block-travel.selectUp':'Select to previous code block','block-travel.selectDown':'Select to next code block','editor.action.surroundWithSnippet':'Wrap selection with a snippet','editor.action.insertSnippet':'Insert a snippet','editor.emmet.action.removeTag':'Remove surrounding HTML tag','editor.emmet.action.matchTag':'Jump to matching HTML tag','composerMode.agent':'Cursor-specific agent command (may be unavailable in VS Code)','editor.action.dirtydiff.next':'Next changed section in the file','editor.action.dirtydiff.previous':'Previous changed section in the file','notebook.diff.action.next':'Next notebook difference','notebook.diff.action.previous':'Previous notebook difference','workbench.action.focusActiveEditorGroup':'Return focus to the editor','git.openFile':'Open source file from a diff','workbench.files.action.createFileFromExplorer':'Create a file in Explorer','git.clean':'Discard selected files’ changes','list.focusUp':'Move up in the focused list','list.focusDown':'Move down in the focused list','list.focusFirst':'First item in the focused list','list.focusLast':'Last item in the focused list','list.focusPageUp':'Page up in the focused list','list.focusPageDown':'Page down in the focused list','runCommands':'Focus search results or the Source Control file list'}
def keyfmt(s):
 for a,b in [('shift','⇧'),('ctrl','⌃'),('alt','⌥'),('cmd','⌘'),('backspace','Backspace'),('escape','Escape'),('left','←'),('right','→'),('down','↓'),('up','↑')]:s=s.replace(a,b)
 return s.replace('+',' ').replace('page↑','Page Up').replace('page↓','Page Down')
bindings=json.loads((R/'editors/vscode/profiles/Cursor Default/keybindings.json').read_text())
rows=[]
for b in bindings:
 if b['command'].startswith('-'):continue
 desc=e(labels.get(b['command'],b['command']))
 if b.get('when'):desc+='<small>'+e(b['when'])+'</small>'
 rows.append((keys(keyfmt(b['key'])),desc))
body+=table(['Shortcut','Action and context'],rows)
body+='''<div class="note warning"><strong>Git discard shortcuts change files.</strong><p><kbd>⌥ ⌘ Z</kbd> discards selected lines in a diff, or selected files in Source Control. Review the selection first. Your profile also contains both Edits History and Go to Last Edit bindings for the same forward shortcut; the active context and installed extensions determine which handles it.</p></div><h3>Restore your editor on another Mac</h3><ol class="steps"><li>Open VS Code’s Profiles menu and choose Import Profile.</li><li>Import the matching <code>.code-profile</code> file from <code>editors/vscode/</code>. It contains current settings, shortcuts, snippets and extension IDs.</li><li>Select Cursor Default for your usual coding workflow. Your live settings are untouched. Core setup leaves VS Code alone; only the optional <code>vscode</code> link profile replaces editor files. Profile IDs are resolved by name.</li></ol><p>Open Keyboard Shortcuts in VS Code to resolve an extension command that no longer exists. The imported Cursor-specific Agent key is preserved but may not do anything in VS Code.</p>'''
